[
  {
    "name": "林逸尘",
    "description": "白衣少年剑客，背负血海深仇的青云宗弃徒，三界大战的破局者",
    "appearance": "19岁少年，剑眉星目，瞳色如墨玉，鼻梁挺直，唇线清冷，长发以一根银白发带束于脑后，几缕碎发随风拂面",
    "costume": "月白色交领广袖长袍，外罩银丝暗纹轻纱氅衣，腰束墨玉腰带，足踏白色皂靴，背负一柄通体晶莹的霜白长剑",
    "personality": "冷峻孤傲、外冷内热、剑心通明，有着少年人特有的执拗与孤勇"
  },
  {
    "name": "苏清音",
    "description": "青云宗主之女，天资卓绝的宗门圣女，与林逸尘有宿命纠缠",
    "appearance": "20岁少女，鹅蛋脸型，杏眼含雾，肤若凝脂，眉心一点朱砂朱印，乌发如瀑斜插一支白玉簪",
    "costume": "水蓝色绣银凤纹广袖流仙裙，外披月白轻纱披帛，颈间一枚暖玉锁骨坠",
    "personality": "温婉端庄、知书达理、内心坚毅，外柔内刚"
  },
  {
    "name": "青云宗主·苏长河",
    "description": "苏清音之父，青云宗掌门，三界大战的统帅",
    "appearance": "50岁中年男子，面如冠玉、鬓若刀裁、目光如炬，颌下一缕长髯",
    "costume": "玄青色金线云纹道袍，头戴白玉束发冠，腰悬掌门玉令",
    "personality": "威严深沉、心怀苍生、城府极深"
  },
  {
    "name": "玄衣长老",
    "description": "青云宗暗藏野心的大长老，三界大战前夜的暗中推手",
    "appearance": "60岁老者，瘦削阴沉，三角眼，眼窝深陷，颧骨高耸",
    "costume": "墨黑色镶暗金边长袍，袖口绣有暗红魔纹",
    "personality": "阴鸷狠辣、笑里藏刀、野心勃勃"
  }
]

[
  {
    "name": "云海之巅·山门外",
    "description": "青云宗悬浮于云海之上的山门入口，巨大石牌坊耸入云端",
    "visualStyle": "夜色如墨，云海翻涌如银浪，月光清冷洒在白玉牌坊上，仙鹤盘旋，长幡飘动，16:9宽银幕构图突出横向延展的云海与高耸的牌坊对比"
  },
  {
    "name": "宗门大殿·夜宴厅",
    "description": "青云宗主殿宴会厅，可容数百人的恢宏殿堂",
    "visualStyle": "千盏宫灯高悬，烛火摇曳如星海，琥珀色酒光映在白玉长案上，帷幔重重如烟，远处仙山云海隐现，16:9宽银幕展现殿堂的纵深与排场"
  },
  {
    "name": "回廊飞檐",
    "description": "大殿外的朱红回廊与飞檐翘角",
    "visualStyle": "朱红漆柱在月光下泛着冷红光泽，夜风拂动轻纱灯笼，远处云海如墨，16:9横构图突出回廊的水平延伸感"
  },
  {
    "name": "云海夜空",
    "description": "青云宗上空，云海与星河交相辉映的夜空",
    "visualStyle": "深蓝夜空，星河璀璨，云海如银色绒毯铺向天际，一轮冷月高悬，16:9横构图展现辽阔天地"
  }
]

{
  "scenes": [
    {
      "location": "云海夜空",
      "time": "夜晚·冷月初升",
      "characters": [
        "林逸尘"
      ],
      "action": "白衣少年林逸尘御剑飞行于云海之上，向青云宗疾驰",
      "dialogue": "（内心独白）十年了，青云宗……我回来了。",
      "mood": "孤冷肃杀、宿命回归的苍凉感"
    },
    {
      "location": "云海之巅·山门外",
      "time": "夜晚",
      "characters": [
        "林逸尘"
      ],
      "action": "林逸尘穿越石牌坊，在山门前驻足凝望灯火辉煌的宗门",
      "dialogue": "",
      "mood": "近乡情怯、繁华与孤寂的反差"
    },
    {
      "location": "宗门大殿·夜宴厅",
      "time": "夜晚",
      "characters": [
        "苏清音",
        "青云宗主·苏长河",
        "玄衣长老",
        "群修"
      ],
      "action": "大殿内觥筹交错，群修齐聚，苏长河举杯致辞，苏清音侍奉在侧",
      "dialogue": "苏长河：今夜群贤毕至，待三界大战过后，本座与诸位共饮庆功酒！",
      "mood": "繁华热闹、歌舞升平下的暗流涌动"
    },
    {
      "location": "回廊飞檐",
      "time": "夜晚",
      "characters": [
        "林逸尘"
      ],
      "action": "林逸尘飞身落在大殿外的回廊上，白衣在夜风中猎猎作响，他望向殿内灯火",
      "dialogue": "",
      "mood": "隐忍克制、蓄势待发"
    },
    {
      "location": "宗门大殿·夜宴厅",
      "time": "夜晚",
      "characters": [
        "林逸尘",
        "苏清音"
      ],
      "action": "林逸尘悄然入殿，途经苏清音身旁，两人四目相对，时光仿佛凝固",
      "dialogue": "苏清音：（低声颤抖）你……你怎么会在这里？",
      "mood": "宿命重逢的震撼与隐痛"
    },
    {
      "location": "宗门大殿·夜宴厅",
      "time": "夜晚",
      "characters": [
        "玄衣长老",
        "林逸尘"
      ],
      "action": "玄衣长老余光瞥见白衣身影，三角眼中闪过一抹阴鸷寒光",
      "dialogue": "",
      "mood": "杀机四伏、危险逼近"
    }
  ]
}
